(function(){
  'use strict';

  const DATA=window.NHF_COURSE;
  const STORAGE_KEY='holusNaturalHealthFundamentalsV2';
  const app=document.getElementById('app');
  const select=document.getElementById('lesson-select');
  const status=document.getElementById('unit-status');
  const nav=[...document.querySelectorAll('[data-view]')];
  const defaults={selectedLesson:1,view:'overview',positions:{},completed:{},confidence:{},checks:{},cards:{},practice:{},answers:{},flags:{},quizPosition:{},review:false};
  let state=load();

  function load(){try{return {...defaults,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}}catch(_){return {...defaults}}}
  function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}
  function esc(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
  function lesson(){return DATA.lessons.find(item=>item.number===Number(state.selectedLesson))||DATA.lessons[0]}
  function lessonId(){return lesson().id}
  function allMoments(item=lesson()){return item.modules.flatMap((module,moduleIndex)=>module.moments.map(moment=>({...moment,module,moduleIndex})))}
  function momentIndex(){return Math.min(Math.max(Number(state.positions[lessonId()]||0),0),Math.max(0,allMoments().length-1))}
  function completedMap(){state.completed[lessonId()]=state.completed[lessonId()]||{};return state.completed[lessonId()]}
  function confidenceMap(){state.confidence[lessonId()]=state.confidence[lessonId()]||{};return state.confidence[lessonId()]}
  function checkMap(){state.checks[lessonId()]=state.checks[lessonId()]||{};return state.checks[lessonId()]}
  function percent(item=lesson()){const moments=allMoments(item);const done=Object.keys(state.completed[item.id]||{}).length;return moments.length?Math.round(done/moments.length*100):0}
  function totalMoments(){return DATA.lessons.reduce((sum,item)=>sum+allMoments(item).length,0)}
  function totalQuestions(){return DATA.lessons.reduce((sum,item)=>sum+item.quiz.length,0)}
  function scrollTopOf(selector='#app'){requestAnimationFrame(()=>{const el=document.querySelector(selector)||app;const offset=matchMedia('(max-width:620px)').matches?18:178;window.scrollTo({top:Math.max(0,el.getBoundingClientRect().top+scrollY-offset),behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})})}
  function sourceLinks(item=lesson()){return item.sources.map((source,index)=>`<a class="source-card" href="${esc(source.url)}" target="_blank" rel="noopener"><span class="source-icon">PDF</span><span><strong>${esc(source.title)}</strong><small>${source.role==='test'?'Official lesson test':'Course reading · opens in Google Drive'}</small></span><span aria-hidden="true">↗</span></a>`).join('')}
  function footer(){return `<p class="footer-note">Natural Health Fundamentals · PDF-grounded study course · progress stays in this browser</p>`}

  function setView(view,push=true){state.view=view;state.review=false;save();if(push)history.replaceState(null,'',view==='learn'?`#lesson-${state.selectedLesson}`:`#${view}`);render();scrollTopOf()}
  function chooseLesson(number,view=state.view){state.selectedLesson=Number(number);state.view=view;state.review=false;save();history.replaceState(null,'',view==='learn'?`#lesson-${number}`:`#${view}`);render();scrollTopOf()}
  function syncHash(){const hash=location.hash.slice(1);const match=hash.match(/^lesson-(\d+)$/);if(match){state.selectedLesson=Math.min(DATA.lessons.length,Math.max(1,Number(match[1])));state.view='learn'}else if(['overview','flashcards','practice','quiz','sources'].includes(hash))state.view=hash}
  function setup(){select.innerHTML=DATA.lessons.map(item=>`<option value="${item.number}">Lesson ${item.number} · ${esc(item.title)}</option>`).join('');select.addEventListener('change',()=>chooseLesson(select.value,state.view==='overview'?'learn':state.view));nav.forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));window.addEventListener('hashchange',()=>{syncHash();render()})}
  function syncChrome(){select.value=String(state.selectedLesson);nav.forEach(button=>button.classList.toggle('active',button.dataset.view===state.view));status.textContent=`${percent()}% learned · ${lesson().sources.length} source PDFs`;document.title=`${state.view==='overview'?'Natural Health Fundamentals':`Lesson ${lesson().number} · ${lesson().title}`} · hōlus.`}

  function renderOverview(){
    const cards=DATA.lessons.map(item=>`<button class="lesson-card ready" type="button" data-lesson="${item.number}"><span class="number">Lesson ${item.number}</span><h4>${esc(item.title)}</h4><p>${allMoments(item).length} learning moments · ${item.practice.length} practice prompts · ${item.quiz.length} official questions</p><span class="lesson-status">${percent(item)}% learned · Open lesson →</span></button>`).join('');
    const complete=DATA.lessons.filter(item=>percent(item)===100).length;
    app.innerHTML=`<div class="ap-shell"><section class="overview-hero"><div><p class="ap-eyebrow">Course 01 · natural health fundamentals</p><h1 class="ap-title">See the whole.<br>Study the parts.</h1><p class="ap-lede">Nine lessons rebuilt directly from the supplied course PDFs. Dense knowledge is paced into focused learning moments, retrieval practice, practitioner cases and the original lesson tests—without hiding the readings.</p><div class="hero-actions"><button class="ap-button" type="button" data-action="continue">Continue Lesson ${state.selectedLesson} →</button><button class="ap-button secondary" type="button" data-view-target="sources">Open source library</button></div><div class="overview-stats"><div class="stat"><strong>${DATA.lessons.length}</strong><span>source-mapped lessons</span></div><div class="stat"><strong>${totalMoments()}</strong><span>focused learning moments</span></div><div class="stat"><strong>${totalQuestions()}</strong><span>official test questions</span></div><div class="stat"><strong>${complete}/9</strong><span>lessons completed</span></div></div><div class="nhf-overview-note"><span>i</span><div><strong>No textbook is assumed.</strong><p>The 54 PDFs in the Natural Health Fundamentals folder are the course source. Every lesson keeps direct links to all six PDFs.</p></div></div></div><div class="overview-art"><img src="../../assets/course-natural-health.svg" alt="A young sprout representing whole-person health learning"></div></section><div class="section-head"><div><p class="ap-eyebrow">Your course map</p><h2>Nine lessons. One consistent learning experience.</h2></div><p>Each lesson follows the same rhythm: understand, connect, retrieve, apply and test.</p></div><div class="lesson-grid">${cards}</div>${footer()}</div>`;
  }

  function renderLearn(){
    const item=lesson(),moments=allMoments(item),index=momentIndex(),current=moments[index],done=completedMap(),selected=checkMap()[current.id],confidence=confidenceMap()[current.id],pct=Math.round(Object.keys(done).length/moments.length*100);
    const rail=moments.map((moment,i)=>`<button class="rail-item ${i===index?'active':''} ${done[moment.id]?'done':''}" type="button" data-moment="${i}"><span>${i+1}</span><b>${esc(moment.title)}</b></button>`).join('');
    const teaching=current.teaching.map(p=>`<p>${esc(p)}</p>`).join('');
    const keyPoints=current.keyPoints.map((p,i)=>`<div class="key-point"><span>High-yield ${i+1}</span><p>${esc(p)}</p></div>`).join('');
    const visual=current.visual.items.map(step=>`<div class="visual-step"><strong>${esc(step.label)}</strong><small>${esc(step.detail)}</small></div>`).join('');
    const options=current.check.options.map((option,i)=>{const chosen=selected===i,revealed=selected!==undefined;return `<button class="check-option ${chosen?'selected':''} ${revealed&&chosen?(option.correct?'correct':'incorrect'):''}" type="button" data-check="${i}"><b>${String.fromCharCode(65+i)}</b><span>${esc(option.text)}</span></button>`}).join('');
    const feedback=selected===undefined?'':`<p class="check-feedback"><strong>${current.check.options[selected].correct?'That connection holds.':'Revisit the distinction.'}</strong> ${esc(current.check.options[selected].feedback)}</p>`;
    app.innerHTML=`<div class="ap-shell learning-shell"><section class="lesson-hero"><div><p class="ap-eyebrow">Lesson ${item.number} · ${esc(current.module.title)}</p><h1 class="ap-title">${esc(item.title)}</h1><p class="ap-lede">${esc(item.lede)}</p><div class="lesson-meta"><span class="meta-chip">${moments.length} learning moments</span><span class="meta-chip">${item.sources.length} source PDFs</span><span class="meta-chip">${item.practice.length} practice prompts</span></div></div><div class="lesson-orbit"><strong>${item.number}</strong></div></section><div class="learning-layout"><aside class="lesson-rail" aria-label="Lesson moments"><p>Lesson route</p>${rail}</aside><section class="learning-stage"><div class="learning-topline"><p><strong>Moment ${index+1} of ${moments.length}</strong> · ${esc(current.module.title)}</p><p>${pct}% complete</p></div><div class="learning-progress" aria-label="Lesson progress"><span style="width:${pct}%"></span></div><article class="moment-card"><div class="moment-kicker"><span>${esc(current.module.label||'Learn')}</span><i>·</i><span>${esc(current.minutes||'8 min')}</span></div><h1>${esc(current.title)}</h1><p class="high-yield">${esc(current.highYield)}</p><div class="teaching-copy">${teaching}</div><div class="key-grid">${keyPoints}</div><section class="visual-model"><h2>${esc(current.visual.title)}</h2><div class="visual-flow">${visual}</div></section><div class="moment-callouts"><aside class="moment-callout mnemonic"><span>Mnemonic</span><p><strong>${esc(current.mnemonic.cue)}</strong><br>${esc(current.mnemonic.explanation)}</p></aside><aside class="moment-callout good"><span>Good to know</span><p>${esc(current.goodToKnow)}</p></aside><aside class="moment-callout practice"><span>In practice as a nutritionist</span><p>${esc(current.inPractice)}</p></aside></div><section class="check-card"><h2>${esc(current.check.prompt)}</h2><div class="check-options">${options}</div>${feedback}</section><section class="confidence-card"><p>How well can you explain this without notes?</p><div class="confidence-row">${['Again','Almost','Got it'].map(label=>`<button type="button" data-confidence="${label}" class="${confidence===label?'active':''}">${label}</button>`).join('')}</div></section></article><div class="learning-pager"><button class="ap-button secondary" type="button" data-action="prev-moment" ${index===0?'disabled':''}>← Previous</button><button class="ap-button" type="button" data-action="next-moment">${index===moments.length-1?'Finish lesson →':'Complete & continue →'}</button></div></section></div>${index===moments.length-1?`<section class="evidence-boundary"><strong>Keep the source boundary:</strong> Completing the learning route does not replace the supplied PDFs. Use Sources to review the original readings and the official test wording.</section>`:''}${footer()}</div>`;
  }

  function renderFlashcards(){
    const item=lesson(),deck=item.flashcards,cardState=state.cards[item.id]||{position:0,flipped:false,mastered:{}};state.cards[item.id]=cardState;cardState.position=Math.min(cardState.position,deck.length-1);const card=deck[cardState.position],mastered=Object.keys(cardState.mastered||{}).length;
    app.innerHTML=`<div class="ap-shell recall-shell"><div class="runner-heading"><div><p class="ap-eyebrow">Lesson ${item.number} · retrieval deck</p><h1>Recall before review.</h1><p>Say the answer aloud, then flip the card. Marking a card as known saves only in this browser.</p></div><div class="runner-stat"><strong>${mastered}/${deck.length}</strong><span>cards marked known</span></div></div><button class="flashcard-card ${cardState.flipped?'flipped':''}" type="button" data-action="flip-card"><span>${cardState.flipped?'Answer':'Prompt'}</span><strong>${esc(cardState.flipped?card.answer:card.prompt)}</strong><small>${cardState.flipped?esc(card.note||'Connect it to the lesson before moving on.'):'Tap to reveal'}</small></button><div class="runner-controls"><button class="ap-button secondary" type="button" data-action="card-prev" ${cardState.position===0?'disabled':''}>← Previous</button><button class="master-button ${cardState.mastered?.[cardState.position]?'active':''}" type="button" data-action="card-master">${cardState.mastered?.[cardState.position]?'✓ Known':'Mark as known'}</button><button class="ap-button" type="button" data-action="card-next" ${cardState.position===deck.length-1?'disabled':''}>Next →</button></div><p class="runner-index">Card ${cardState.position+1} of ${deck.length}</p>${footer()}</div>`;
  }

  function renderPractice(){
    const item=lesson(),items=item.practice,pState=state.practice[item.id]||{position:0,revealed:false,completed:{}};state.practice[item.id]=pState;pState.position=Math.min(pState.position,items.length-1);const current=items[pState.position];
    app.innerHTML=`<div class="ap-shell practice-shell"><div class="runner-heading"><div><p class="ap-eyebrow">Lesson ${item.number} · formative practice</p><h1>Explain, then check.</h1><p>These 10–12 prompts prepare you for the separate official lesson test. Try each response before revealing the teaching answer.</p></div><div class="runner-stat"><strong>${Object.keys(pState.completed||{}).length}/${items.length}</strong><span>prompts reviewed</span></div></div><article class="practice-card"><span>${esc(current.tag||'Retrieval prompt')}</span><h2>${esc(current.prompt)}</h2>${pState.revealed?`<div class="practice-answer"><strong>Teaching answer</strong><p>${esc(current.answer)}</p><b>Why it matters</b><p>${esc(current.rationale)}</p></div>`:`<button class="ap-button" type="button" data-action="practice-reveal">Reveal teaching answer</button>`}</article><div class="runner-controls"><button class="ap-button secondary" type="button" data-action="practice-prev" ${pState.position===0?'disabled':''}>← Previous</button><span class="runner-index">Prompt ${pState.position+1} of ${items.length}</span><button class="ap-button" type="button" data-action="practice-next">${pState.position===items.length-1?'Go to official quiz →':'Next prompt →'}</button></div>${footer()}</div>`;
  }

  function quizPosition(item=lesson()){return Math.min(Math.max(Number(state.quizPosition[item.id]||0),0),Math.max(0,item.quiz.length-1))}
  function renderQuiz(){
    const item=lesson();if(state.review){renderQuizReview();return}const index=quizPosition(item),question=item.quiz[index],saved=state.answers[item.id]||{},flags=state.flags[item.id]||{},chosen=saved[question.number],answered=Object.keys(saved).length;
    const options=question.options.map((option,i)=>`<label class="quiz-option ${Number(chosen)===i?'selected':''}"><input type="radio" name="nhf-answer" value="${i}" ${Number(chosen)===i?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b>${esc(option)}</span></label>`).join('');
    const map=item.quiz.map((q,i)=>`<button type="button" data-question="${i}" class="${i===index?'current':''} ${saved[q.number]!==undefined?'answered':''} ${flags[q.number]?'flagged':''}">${q.number}</button>`).join('');
    app.innerHTML=`<div class="ap-shell quiz-shell"><div class="quiz-heading"><div><p class="ap-eyebrow">Lesson ${item.number} · official supplied test</p><h1 class="${item.title.length>28?'long-title':''}">${esc(item.title)}</h1></div><div><strong>${answered}/${item.quiz.length}</strong><span>responses saved</span></div></div><div class="quiz-alert"><strong>Source-faithful mode:</strong> official question wording is preserved. The printer PDFs do not include answer keys, so each course answer is transparently inferred from the supplied lesson text. Dated or scientifically weak items carry a separate evidence note.</div><div class="quiz-progress"><span style="width:${Math.round(answered/item.quiz.length*100)}%"></span></div><div class="quiz-layout"><article class="question-card"><span class="question-kicker">Question ${question.number} of ${item.quiz.length}</span><h2>${esc(question.prompt)}</h2><div class="option-list">${options}</div><div class="quiz-controls"><button class="ap-button secondary" type="button" data-action="quiz-prev" ${index===0?'disabled':''}>← Previous</button><div class="middle"><button class="flag-button ${flags[question.number]?'active':''}" type="button" data-action="toggle-flag">${flags[question.number]?'Flagged':'Flag for review'}</button><button class="ap-button" type="button" data-action="quiz-next">${index===item.quiz.length-1?'Review answers →':'Next →'}</button></div></div></article><aside class="quiz-side"><h3>Question map</h3><p>Responses save automatically in this browser.</p><div class="question-map">${map}</div><button class="ap-button secondary" type="button" data-action="review" style="width:100%;margin-top:18px">Review now</button></aside></div>${footer()}</div>`;
  }

  function renderQuizReview(){
    const item=lesson(),saved=state.answers[item.id]||{},scorable=item.quiz.filter(q=>Number.isInteger(q.answer)),correct=scorable.filter(q=>Number(saved[q.number])===q.answer).length,answered=Object.keys(saved).length;
    const rows=item.quiz.map(q=>{const chosen=saved[q.number],isCorrect=Number(chosen)===q.answer;return `<article class="response-row"><b>${q.number}</b><span>${esc(q.prompt)}<small style="display:block;margin-top:6px;color:var(--holus-muted)">${chosen===undefined?'Not answered':`Your answer: ${esc(q.options[chosen])}`}</small>${q.evidenceNote?`<small style="display:block;margin-top:6px;color:#7a4c3a"><strong>Evidence note:</strong> ${esc(q.evidenceNote)}</small>`:''}</span><em class="response-status ${chosen===undefined?'flagged':isCorrect?'correct':'retry'}">${chosen===undefined?'Open':isCorrect?'Correct':'Review'}</em></article>`}).join('');
    app.innerHTML=`<div class="ap-shell quiz-shell"><article class="review-card"><p class="ap-eyebrow">Lesson ${item.number} · quiz review</p><h1 class="ap-title">Use the misses.</h1><p class="ap-lede">The score uses the course answer inferred from the supplied lesson text because the printer test includes no answer key. Evidence notes identify dated or problematic wording so memorization does not replace sound understanding.</p><div class="review-summary"><div class="review-stat"><strong>${answered}/${item.quiz.length}</strong><span>answered</span></div><div class="review-stat"><strong>${correct}/${scorable.length}</strong><span>matched inferred key</span></div><div class="review-stat"><strong>${Object.keys(state.flags[item.id]||{}).filter(k=>state.flags[item.id][k]).length}</strong><span>flagged</span></div></div><div class="response-list">${rows}</div><div class="hero-actions"><button class="ap-button" type="button" data-action="return-quiz">Return to questions</button><button class="ap-button secondary" type="button" data-action="first-unanswered">First unanswered</button></div></article>${footer()}</div>`;
  }

  function renderSources(){
    const item=lesson(),manifest=DATA.lessons.map(l=>`<div class="manifest-lesson"><b>Lesson ${l.number} · ${esc(l.title)}</b><span>${l.sources.length} PDFs · ${l.quiz.length} official questions</span></div>`).join('');
    app.innerHTML=`<div class="sources-shell"><section class="sources-head"><div><p class="ap-eyebrow">Lesson ${item.number} · source library</p><h1>Read the originals.</h1><p>Every teaching moment in this course is mapped to the supplied Natural Health Fundamentals PDFs. Open any reading in Google Drive when you want the full document, original wording or printer-version lesson test.</p></div><aside class="source-policy"><strong>Source boundary</strong><p>Some readings contain historical statistics, promotional language or claims that need modern context. The learning layer preserves the course meaning while marking these boundaries.</p></aside></section><div class="source-list">${sourceLinks(item)}</div><section class="all-sources"><p class="ap-eyebrow">Complete manifest</p><h2>54 PDFs · nine lessons · six documents each</h2><div class="manifest-grid">${manifest}</div></section>${footer()}</div>`;
  }

  function render(){syncChrome();if(state.view==='overview')renderOverview();else if(state.view==='learn')renderLearn();else if(state.view==='flashcards')renderFlashcards();else if(state.view==='practice')renderPractice();else if(state.view==='quiz')renderQuiz();else renderSources()}

  app.addEventListener('change',event=>{if(event.target.name!=='nhf-answer')return;const item=lesson(),q=item.quiz[quizPosition(item)];state.answers[item.id]=state.answers[item.id]||{};state.answers[item.id][q.number]=Number(event.target.value);save();renderQuiz()});
  app.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.lesson){chooseLesson(target.dataset.lesson,'learn');return}if(target.dataset.viewTarget){setView(target.dataset.viewTarget);return}if(target.dataset.moment!==undefined){state.positions[lessonId()]=Number(target.dataset.moment);save();renderLearn();scrollTopOf('.learning-topline');return}if(target.dataset.check!==undefined){const current=allMoments()[momentIndex()];checkMap()[current.id]=Number(target.dataset.check);save();renderLearn();return}if(target.dataset.confidence){const current=allMoments()[momentIndex()];confidenceMap()[current.id]=target.dataset.confidence;save();renderLearn();return}if(target.dataset.question!==undefined){state.quizPosition[lessonId()]=Number(target.dataset.question);state.review=false;save();renderQuiz();scrollTopOf('.quiz-heading');return}const action=target.dataset.action;if(!action)return;const item=lesson();if(action==='continue')setView('learn');else if(action==='prev-moment'){state.positions[item.id]=Math.max(0,momentIndex()-1);save();renderLearn();scrollTopOf('.learning-topline')}else if(action==='next-moment'){const moments=allMoments(),index=momentIndex();completedMap()[moments[index].id]=true;if(index===moments.length-1){save();setView('practice');return}state.positions[item.id]=index+1;save();renderLearn();scrollTopOf('.learning-topline')}else if(action==='flip-card'){state.cards[item.id].flipped=!state.cards[item.id].flipped;save();renderFlashcards()}else if(action==='card-prev'){state.cards[item.id].position=Math.max(0,state.cards[item.id].position-1);state.cards[item.id].flipped=false;save();renderFlashcards()}else if(action==='card-next'){state.cards[item.id].position=Math.min(item.flashcards.length-1,state.cards[item.id].position+1);state.cards[item.id].flipped=false;save();renderFlashcards()}else if(action==='card-master'){const card=state.cards[item.id];card.mastered=card.mastered||{};card.mastered[card.position]=!card.mastered[card.position];save();renderFlashcards()}else if(action==='practice-reveal'){const p=state.practice[item.id];p.revealed=true;p.completed[p.position]=true;save();renderPractice()}else if(action==='practice-prev'){const p=state.practice[item.id];p.position=Math.max(0,p.position-1);p.revealed=false;save();renderPractice()}else if(action==='practice-next'){const p=state.practice[item.id];p.completed[p.position]=true;if(p.position===item.practice.length-1){save();setView('quiz');return}p.position+=1;p.revealed=false;save();renderPractice()}else if(action==='quiz-prev'){state.quizPosition[item.id]=Math.max(0,quizPosition(item)-1);save();renderQuiz();scrollTopOf('.quiz-heading')}else if(action==='quiz-next'){const next=quizPosition(item)+1;if(next>=item.quiz.length)state.review=true;else state.quizPosition[item.id]=next;save();renderQuiz();scrollTopOf('.quiz-heading')}else if(action==='toggle-flag'){const q=item.quiz[quizPosition(item)];state.flags[item.id]=state.flags[item.id]||{};state.flags[item.id][q.number]=!state.flags[item.id][q.number];save();renderQuiz()}else if(action==='review'){state.review=true;save();renderQuiz()}else if(action==='return-quiz'){state.review=false;save();renderQuiz()}else if(action==='first-unanswered'){const saved=state.answers[item.id]||{},index=item.quiz.findIndex(q=>saved[q.number]===undefined);state.quizPosition[item.id]=Math.max(0,index);state.review=false;save();renderQuiz()}});

  syncHash();setup();render();
})();
